const config = $('Config').first().json;
const body = $('Webhook').first().json.body ?? {};
const data = body.data ?? {};
const key = data.key ?? {};
const digits = (value) => String(value ?? '').split('@')[0].replace(/\D/g, '');
const owner = digits(config.ownerNumber);
const chat = [key.remoteJid, key.remoteJidAlt, key.senderPn].filter(Boolean).map(digits);
const text =
  data.message?.conversation ?? data.message?.extendedTextMessage?.text ?? '';
if (body.event && !/messages[._-]?upsert/i.test(body.event)) return [];
if (!owner || !text.trim() || text.trim().startsWith('🤖')) return [];
const selfChat = key.fromMe === true && chat.includes(owner);
const fromOwner = key.fromMe !== true && chat.includes(owner);
if (!selfChat && !fromOwner) return [];
return [{ json: { text, messageId: key.id ?? String(Date.now()), number: owner } }];

const normalize = (value) =>
  String(value ?? "")
    .normalize("NFD")
    .replace(/[̀-ͯ]/g, "")
    .toLowerCase()
    .replace(/[^a-z0-9]/g, "");

const money = (cents) => {
  const sign = cents < 0 ? "-" : "";
  const abs = Math.abs(Math.round(cents));
  const whole = String(Math.floor(abs / 100)).replace(/\B(?=(\d{3})+(?!\d))/g, " ");
  return `${sign}${whole},${String(abs % 100).padStart(2, "0")}`;
};

const toCents = (raw) => {
  let text = String(raw).replace(/\s/g, "");
  if (!/^[\d.,]+$/.test(text)) return null;
  if (text.includes(",")) text = text.replace(/\./g, "").replace(",", ".");
  else if (/^\d{1,3}(\.\d{3})+$/.test(text)) text = text.replace(/\./g, "");
  const value = Number(text);
  if (!Number.isFinite(value) || value <= 0) return null;
  return Math.round(value * 100);
};

const pick = (items, wanted, label) => {
  const key = normalize(wanted);
  if (!key) return { error: `Falta o nome da ${label}.` };
  for (const test of [
    (name) => name === key,
    (name) => name.startsWith(key),
    (name) => name.includes(key),
  ]) {
    const found = items.filter((item) => test(normalize(item.name)));
    if (found.length === 1) return { item: found[0] };
    if (found.length > 1)
      return { error: `Qual ${label}? ${found.map((item) => item.name).join(" / ")}` };
  }
  return {
    error: `Não encontrei a ${label} "${wanted}". Opções: ${items.map((item) => item.name).join(", ")}`,
  };
};

const uuidFrom = (text) => {
  let h1 = 1779033703, h2 = 3144134277, h3 = 1013904242, h4 = 2773480762;
  const input = `wallet-whatsapp:${text}`;
  for (let i = 0; i < input.length; i++) {
    const k = input.charCodeAt(i);
    h1 = h2 ^ Math.imul(h1 ^ k, 597399067);
    h2 = h3 ^ Math.imul(h2 ^ k, 2869860233);
    h3 = h4 ^ Math.imul(h3 ^ k, 951274213);
    h4 = h1 ^ Math.imul(h4 ^ k, 2716044179);
  }
  h1 = Math.imul(h3 ^ (h1 >>> 18), 597399067);
  h2 = Math.imul(h4 ^ (h2 >>> 22), 2869860233);
  h3 = Math.imul(h1 ^ (h3 >>> 17), 951274213);
  h4 = Math.imul(h2 ^ (h4 >>> 19), 2716044179);
  const hex = [h1 ^ h2 ^ h3 ^ h4, h2 ^ h1, h3 ^ h1, h4 ^ h1]
    .map((h) => (h >>> 0).toString(16).padStart(8, "0"))
    .join("");
  const variant = ((parseInt(hex[16], 16) & 0x3) | 0x8).toString(16);
  return `${hex.slice(0, 8)}-${hex.slice(8, 12)}-5${hex.slice(13, 16)}-${variant}${hex.slice(17, 20)}-${hex.slice(20, 32)}`;
};

const MARK = "🤖";

const HELP = [
  "Comandos:",
  "saldo",
  "- 250 mpesa pão  (saída)",
  "+ 5000 bci salário  (entrada)",
  "t 1000 bci mpesa  (transferência)",
  "Opcional: #categoria no fim, ex.: - 250 mpesa pão #alimentação",
].join("\n");

function interpret({ text, messageId, accounts, categories, now }) {
  const message = String(text ?? "").trim();
  const total = accounts.reduce((sum, account) => sum + account.balance, 0);

  if (/^saldo$/i.test(message)) {
    const lines = accounts.map((account) => `${account.name}: ${money(account.balance)}`);
    return { reply: [...lines, `Total: ${money(total)} MZN`].join("\n") };
  }

  const transfer = message.match(/^t\s+([\d.,]+)\s+(\S+)\s+(\S+)\s*(.*)$/i);
  if (transfer) {
    const amount = toCents(transfer[1]);
    if (!amount) return { reply: `Valor inválido: ${transfer[1]}\n\n${HELP}` };
    const from = pick(accounts, transfer[2], "conta de origem");
    if (from.error) return { reply: from.error };
    const to = pick(accounts, transfer[3], "conta de destino");
    if (to.error) return { reply: to.error };
    if (from.item.id === to.item.id)
      return { reply: "A conta de origem e a de destino têm de ser diferentes." };
    return {
      write: {
        path: "/api/transfers",
        body: {
          id: uuidFrom(messageId),
          fromAccountId: from.item.id,
          toAccountId: to.item.id,
          amount,
          occurredAt: now,
          note: transfer[4].trim() || null,
        },
      },
      summary: `Transferência ${money(amount)} MZN · ${from.item.name} → ${to.item.name}`,
      accountIds: [from.item.id, to.item.id],
    };
  }

  const entry = message.match(/^([+-])\s*([\d.,]+)\s+(\S+)\s*(.*)$/);
  if (entry) {
    const type = entry[1] === "+" ? "income" : "expense";
    const amount = toCents(entry[2]);
    if (!amount) return { reply: `Valor inválido: ${entry[2]}\n\n${HELP}` };
    const account = pick(accounts, entry[3], "conta");
    if (account.error) return { reply: account.error };
    const tag = entry[4].match(/(?:^|\s)#(\S+)/);
    const note = entry[4].replace(/(?:^|\s)#\S+/g, "").trim() || null;
    let categoryId = null;
    let categoryName = "";
    if (tag) {
      const options = categories.filter((c) => c.kind === type && !c.archived);
      const category = pick(options, tag[1], "categoria");
      if (category.error) return { reply: category.error };
      categoryId = category.item.id;
      categoryName = ` · ${category.item.name}`;
    }
    return {
      write: {
        path: "/api/transactions",
        body: {
          id: uuidFrom(messageId),
          type,
          accountId: account.item.id,
          categoryId,
          amount,
          occurredAt: now,
          note,
        },
      },
      summary: `${type === "income" ? "Entrada" : "Saída"} ${money(amount)} MZN · ${account.item.name}${categoryName}`,
      accountIds: [account.item.id],
    };
  }

  if (/^(ajuda|help|\?)$/i.test(message)) return { reply: HELP };
  return {};
}

function afterWrite({ summary, accountIds, accounts, error }) {
  if (error) return `❌ Não gravei: ${error}`;
  const balances = accountIds
    .map((id) => accounts.find((account) => account.id === id))
    .filter(Boolean)
    .map((account) => `${account.name}: ${money(account.balance)}`);
  return [`✅ ${summary}`, "Saldo agora:", ...balances].join("\n");
}


